PRAGMA foreign_keys=OFF;BEGIN TRANSACTION;CREATE TABLE adaptive_tasks (
	id INTEGER NOT NULL, 
	class_level INTEGER NOT NULL, 
	difficulty_level INTEGER NOT NULL, 
	topic VARCHAR(200) NOT NULL, 
	subtopic VARCHAR(100), 
	task_text TEXT NOT NULL, 
	solution TEXT NOT NULL, 
	criteria_1_point TEXT NOT NULL, 
	criteria_2_points TEXT NOT NULL, 
	created_at DATETIME, 
	correct_answer TEXT, 
	is_flagged BOOLEAN, 
	reports_count INTEGER, 
	flagged_reason TEXT, 
	attempts_count INTEGER, 
	solves_count INTEGER, 
	actual_solve_rate FLOAT, 
	suggested_level INTEGER, 
	needs_reclassification BOOLEAN, 
	last_calibrated_at DATETIME, 
	subject VARCHAR(20), 
	source_id VARCHAR(120), 
	needs_review BOOLEAN, 
	llm_suggested_answer TEXT, 
	llm_suggested_solution TEXT, 
	review_reason TEXT, 
	review_flagged_at DATETIME, 
	PRIMARY KEY (id)
);INSERT INTO "adaptive_tasks" VALUES(1,5,1,'Теория чисел. Делимость и остатки','Делимость и остатки','У Пети есть карточки с числами от \(14\) до \(20\). Можно ли разложить все карточки на две группы так, чтобы суммы чисел в группах были равны?','Сумма всех чисел равна \(14+15+16+17+18+19+20=119\). Если бы карточки можно было разделить на две группы с равными суммами, общая сумма была бы чётной. Но \(119\) нечётно, значит такое разбиение невозможно.','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','Нельзя.',0,0,NULL,0,0,NULL,NULL,0,NULL,'number_theory','math_g5_natural_numbers_l3_t0060',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(2,5,4,'Логика. Логика и стратегии','Логика и стратегии','На доске написаны числа от \(1\) до \(61\). За ход два числа заменяют их суммой. Можно ли в конце получить \(1892\)?','Сумма чисел сохраняется. Начальная сумма равна \(61\cdot62:2=1891\), поэтому в конце не может получиться \(1892\).','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','Нет',0,0,NULL,0,0,NULL,NULL,0,NULL,'logic','math_g5_natural_numbers_l3_t0062',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(3,5,1,'Теория чисел. Делимость и остатки','Делимость и остатки','Найдите наименьшее натуральное число, которое при делении на \(2\), \(3\) и \(4\) даёт остатки соответственно \(1\), \(2\) и \(3\).','Условия означают, что число на \(1\) меньше числа, делящегося на \(2\), \(3\) и \(4\). Значит искомое число имеет вид \(12k-1\), потому что \(\operatorname{lcm}(2,3,4)=12\). Наименьшее натуральное такое число равно \(12\cdot1-1=11\). Проверка: \(11\equiv1\pmod2\), \(11\equiv2\pmod3\), \(11\equiv3\pmod4\).','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','\(11\)',0,0,NULL,0,0,NULL,NULL,0,NULL,'number_theory','math_g5_natural_numbers_l4_t0089',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(4,5,4,'Логика. Логика и стратегии','Логика и стратегии','На доске написаны числа от \(1\) до \(68\). За ход два числа заменяют их суммой. Можно ли в конце получить \(2347\)?','Сумма чисел сохраняется. Начальная сумма равна \(68\cdot69:2=2346\), поэтому в конце не может получиться \(2347\).','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','Нет',0,0,NULL,0,0,NULL,NULL,0,NULL,'logic','math_g5_natural_numbers_l4_t0091',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(5,5,4,'Логика. Логика и стратегии','Логика и стратегии','На доске написаны числа от \(1\) до \(48\). За ход два числа заменяют их суммой. Можно ли в конце получить \(1177\)?','Сумма чисел сохраняется. Начальная сумма равна \(48\cdot49:2=1176\), поэтому в конце не может получиться \(1177\).','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','Нет',0,0,NULL,0,0,NULL,NULL,0,NULL,'logic','math_g5_natural_numbers_l4_t0111',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(6,5,1,'Теория чисел. Делимость и остатки','Делимость и остатки','Можно ли перед числами \(1,2,3,\ldots,20\) поставить знаки плюс или минус так, чтобы итоговая сумма была равна \(0\)?','Общая сумма чисел от \(1\) до \(20\) равна \(210\). Чтобы итоговая сумма стала \(0\), достаточно выбрать часть чисел с суммой \(105\) и поставить перед ними плюс, а перед остальными минус. Например, \(20+19+18+17+16+15=105\). Значит перед этими шестью числами ставим плюс, перед всеми остальными минус, и суммы двух групп равны.','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','Можно.',0,0,NULL,0,0,NULL,NULL,0,NULL,'number_theory','math_g5_natural_numbers_l4_t0113',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(7,5,4,'Теория чисел. Делимость и остатки','Делимость и остатки','На доске число \(36\). За ход можно прибавить или вычесть \(2\), не уходя ниже нуля. Можно ли получить \(226\)?','Чётность сохраняется, а числа \(36\) и \(226\) одной чётности. Так как цель больше начального числа, достаточно \(95\) раз прибавить \(2\).','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','Да',0,0,NULL,0,0,NULL,NULL,0,NULL,'number_theory','math_g5_natural_numbers_l5_t0117',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(8,5,1,'Теория чисел. Делимость и остатки','Делимость и остатки','На столе \(332\) камней. За ход можно взять от \(1\) до \(3\) камней. Кто берёт последний, выигрывает. Как играть второму?','Если первый взял \(r\) камней, второй берёт \(4-r\). Тогда за пару ходов уходит ровно \(4\) камня. Так как начальное число кратно \(4\), последний ход сделает второй.','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','Отвечать до суммы \(4\) за пару ходов',0,0,NULL,0,0,NULL,NULL,0,NULL,'number_theory','math_g5_natural_numbers_l5_t0119',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(9,5,4,'Теория чисел. Делимость и остатки','Делимость и остатки','На доске число \(91\). За ход можно прибавить или вычесть \(2\), не уходя ниже нуля. Можно ли получить \(231\)?','Чётность сохраняется, а числа \(91\) и \(231\) одной чётности. Так как цель больше начального числа, достаточно \(70\) раз прибавить \(2\).','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','Да',0,0,NULL,0,0,NULL,NULL,0,NULL,'number_theory','math_g5_natural_numbers_l6_t0161',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(10,5,1,'Теория чисел. Делимость и остатки','Делимость и остатки','На столе \(168\) камней. За ход можно взять от \(1\) до \(3\) камней. Кто берёт последний, выигрывает. Как играть второму?','Если первый взял \(r\) камней, второй берёт \(4-r\). Тогда за пару ходов уходит ровно \(4\) камня. Так как начальное число кратно \(4\), последний ход сделает второй.','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','Отвечать до суммы \(4\) за пару ходов',0,0,NULL,0,0,NULL,NULL,0,NULL,'number_theory','math_g5_natural_numbers_l6_t0163',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(11,5,4,'Теория чисел. Делимость и остатки','Делимость и остатки','На доске число \(14\). За ход можно прибавить или вычесть \(2\), не уходя ниже нуля. Можно ли получить \(200\)?','Чётность сохраняется, а числа \(14\) и \(200\) одной чётности. Так как цель больше начального числа, достаточно \(93\) раз прибавить \(2\).','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','Да',0,0,NULL,0,0,NULL,NULL,0,NULL,'number_theory','math_g5_natural_numbers_l7_t0197',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(12,5,1,'Теория чисел. Делимость и остатки','Делимость и остатки','На столе \(228\) камней. За ход можно взять от \(1\) до \(3\) камней. Кто берёт последний, выигрывает. Как играть второму?','Если первый взял \(r\) камней, второй берёт \(4-r\). Тогда за пару ходов уходит ровно \(4\) камня. Так как начальное число кратно \(4\), последний ход сделает второй.','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','Отвечать до суммы \(4\) за пару ходов',0,0,NULL,0,0,NULL,NULL,0,NULL,'number_theory','math_g5_natural_numbers_l7_t0199',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(13,5,2,'Алгебра. Дроби, доли, проценты','Дроби, доли, проценты','Какая дробь больше: \(2/6\) или \(3/6\)?','У дробей одинаковый знаменатель. Больше та дробь, у которой числитель больше.','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','\(3/6\)',0,0,NULL,0,0,NULL,NULL,0,NULL,'algebra','math_g5_fractions_decimals_percent_l1_t0005',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(14,5,2,'Алгебра. Дроби, доли, проценты','Дроби, доли, проценты','Какая дробь больше: \(8/10\) или \(9/10\)?','У дробей одинаковый знаменатель. Больше та дробь, у которой числитель больше.','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','\(9/10\)',0,0,NULL,0,0,NULL,NULL,0,NULL,'algebra','math_g5_fractions_decimals_percent_l1_t0021',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(15,5,2,'Алгебра. Дроби, доли, проценты','Дроби, доли, проценты','Какая дробь больше: \(7/9\) или \(8/9\)?','У дробей одинаковый знаменатель. Больше та дробь, у которой числитель больше.','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','\(8/9\)',0,0,NULL,0,0,NULL,NULL,0,NULL,'algebra','math_g5_fractions_decimals_percent_l2_t0050',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(16,5,1,'Алгебра. Натуральные числа и арифметика','Натуральные числа и арифметика','Число \(396\) увеличили на его четверть. Какое число получилось?','Четверть числа равна \(396:4=99\). Получилось \(396+99=495\).','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','\(495\)',0,0,NULL,0,0,NULL,NULL,0,NULL,'algebra','math_g5_fractions_decimals_percent_l3_t0060',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(17,5,2,'Алгебра. Дроби, доли, проценты','Дроби, доли, проценты','Петя прошёл \(5/6\) пути утром и \(1/6\) пути вечером. Какую часть пути он прошёл?','Складываем части с одинаковым знаменателем: \(5/6+1/6=6/6\). Сокращаем дробь: \(6/6=1\).','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','\(1\)',0,0,NULL,0,0,NULL,NULL,0,NULL,'algebra','math_g5_fractions_decimals_percent_l3_t0061',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(18,5,1,'Алгебра. Натуральные числа и арифметика','Натуральные числа и арифметика','Число \(104\) увеличили на его четверть. Какое число получилось?','Четверть числа равна \(104:4=26\). Получилось \(104+26=130\).','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','\(130\)',0,0,NULL,0,0,NULL,NULL,0,NULL,'algebra','math_g5_fractions_decimals_percent_l4_t0089',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(19,5,2,'Алгебра. Дроби, доли, проценты','Дроби, доли, проценты','Петя прошёл \(2/10\) пути утром и \(4/10\) пути вечером. Какую часть пути он прошёл?','Складываем части с одинаковым знаменателем: \(2/10+4/10=6/10\). Сокращаем дробь: \(6/10=3/5\).','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','\(3/5\)',0,0,NULL,0,0,NULL,NULL,0,NULL,'algebra','math_g5_fractions_decimals_percent_l4_t0090',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(20,5,1,'Алгебра. Натуральные числа и арифметика','Натуральные числа и арифметика','Число \(392\) увеличили на его четверть. Какое число получилось?','Четверть числа равна \(392:4=98\). Получилось \(392+98=490\).','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','\(490\)',0,0,NULL,0,0,NULL,NULL,0,NULL,'algebra','math_g5_fractions_decimals_percent_l4_t0113',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(21,5,2,'Алгебра. Дроби, доли, проценты','Дроби, доли, проценты','Петя прошёл \(2/8\) пути утром и \(4/8\) пути вечером. Какую часть пути он прошёл?','Складываем части с одинаковым знаменателем: \(2/8+4/8=6/8\). Сокращаем дробь: \(6/8=3/4\).','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','\(3/4\)',0,0,NULL,0,0,NULL,NULL,0,NULL,'algebra','math_g5_fractions_decimals_percent_l4_t0114',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(22,5,4,'Комбинаторика. Комбинаторика и подсчёт','Комбинаторика и подсчёт','В классе \(24\) ученика. Учитель хочет выбрать из них \(2\) дежурных. Сколькими способами это можно сделать, если порядок дежурных не важен?','Это число неупорядоченных пар учеников: \(\binom{24}{2}=\dfrac{24\cdot 23}{2}=\dfrac{552}{2}=276\). Поэтому существует \(276\) способов выбрать двух дежурных.','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','\(276\)',0,0,NULL,0,0,NULL,NULL,0,NULL,'combinatorics','math_g5_fractions_decimals_percent_l5_t0117',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(23,5,2,'Алгебра. Дроби, доли, проценты','Дроби, доли, проценты','Что больше: \(10\%\) от \(273\) или \(1/5\) от \(273\)?','\(10\%\) — это \(1/10\) числа, а \(1/5\) больше, чем \(1/10\). Поэтому для положительного числа \(273\) больше его пятая часть.','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','\(1/5\) от числа',0,0,NULL,0,0,NULL,NULL,0,NULL,'algebra','math_g5_fractions_decimals_percent_l5_t0118',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(24,5,2,'Теория чисел. Делимость и остатки','Делимость и остатки','Можно ли разделить \(13\) одинаковых яблок между \(12\) детьми так, чтобы каждый получил целое число яблок и всем досталось поровну?','Для равного деления на \(12\) детей число яблок должно делиться на \(12\). Число \(13\) даёт остаток \(1\) при делении на \(12\), значит так разделить нельзя.','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','Нет',0,0,NULL,0,0,NULL,NULL,0,NULL,'number_theory','math_g5_fractions_decimals_percent_l5_t0119',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(25,5,1,'Алгебра. Дроби, доли, проценты','Дроби, доли, проценты','Есть \(140\) конфет. За ход можно взять четверть оставшихся конфет, если это целое число. Сколько останется после первого хода?','Четверть от \(140\) равна \(35\). После взятия останется \(140-35=105\). Дополнительно проверяем условие: все использованные величины натуральные или допустимые для данного класса, а вывод следует из общего свойства, а не из угадывания ответа.','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','\(105\)',0,0,NULL,0,0,NULL,NULL,0,NULL,'algebra','math_g5_fractions_decimals_percent_l5_t0120',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(26,5,2,'Теория чисел. Делимость и остатки','Делимость и остатки','Можно ли разделить \(12\) одинаковых яблок между \(11\) детьми так, чтобы каждый получил целое число яблок и всем досталось поровну?','Для равного деления на \(11\) детей число яблок должно делиться на \(11\). Число \(12\) даёт остаток \(1\) при делении на \(11\), значит так разделить нельзя.','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','Нет',0,0,NULL,0,0,NULL,NULL,0,NULL,'number_theory','math_g5_fractions_decimals_percent_l6_t0147',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(27,5,4,'Комбинаторика. Комбинаторика и подсчёт','Комбинаторика и подсчёт','На полке стоит \(7\) различных книг. Сколькими способами их можно расставить в ряд?','Число перестановок \(7\) различных объектов равно \(7!=7\cdot 6\cdot 5\cdot 4\cdot 3\cdot 2\cdot 1=5040\). Значит существует \(5040\) различных расстановок книг.','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','\(5040\)',0,0,NULL,0,0,NULL,NULL,0,NULL,'combinatorics','math_g5_fractions_decimals_percent_l6_t0157',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(28,5,1,'Алгебра. Дроби, доли, проценты','Дроби, доли, проценты','Есть \(88\) конфет. За ход можно взять четверть оставшихся конфет, если это целое число. Сколько останется после первого хода?','Четверть от \(88\) равна \(22\). После взятия останется \(88-22=66\). Дополнительно проверяем условие: все использованные величины натуральные или допустимые для данного класса, а вывод следует из общего свойства, а не из угадывания ответа.','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026-05-27 20:45:31','\(66\)',0,0,NULL,0,0,NULL,NULL,0,NULL,'algebra','math_g5_fractions_decimals_percent_l6_t0160',NULL,NULL,NULL,NULL,NULL);INSERT INTO "adaptive_tasks" VALUES(29,5,2,'Алгебра. Дроби, доли, проценты','Дроби, доли, проценты','Что больше: \(10\%\) от \(260\) или \(1/5\) от \(260\)?','\(10\%\) — это \(1/10\) числа, а \(1/5\) больше, чем \(1/10\). Поэтому для положительного числа \(260\) больше его пятая часть.','(критерий 1 балл — не задан)','(критерий 2 балла — не задан)','2026