'2026-05-26 18:32:36.685116');INSERT INTO "olympiad_probniks" VALUES(12,'vsosh-9-2027-stage-2','stage',2,'Этапный пробник 2 (название ждёт текста)',NULL,'ВсОШ',9,2027,210,35,NULL,NULL,102,1,'2026-05-26 18:32:36.686650');INSERT INTO "olympiad_probniks" VALUES(13,'vsosh-9-2027-stage-3','stage',3,'Этапный пробник 3 (название ждёт текста)',NULL,'ВсОШ',9,2027,210,35,NULL,NULL,103,1,'2026-05-26 18:32:36.688184');INSERT INTO "olympiad_probniks" VALUES(14,'vsosh-9-2027-stage-4','stage',4,'Этапный пробник 4 (название ждёт текста)',NULL,'ВсОШ',9,2027,240,35,NULL,NULL,104,1,'2026-05-26 18:32:36.689202');INSERT INTO "olympiad_probniks" VALUES(15,'vsosh-9-2027-stage-5','stage',5,'Этапный пробник 5 (название ждёт текста)',NULL,'ВсОШ',9,2027,240,28,NULL,NULL,105,1,'2026-05-26 18:32:36.690187');CREATE TABLE olympiad_secrets (
