	device_id VARCHAR(64), 
	test_type VARCHAR(50) NOT NULL, 
	class_level INTEGER, 
	topic VARCHAR(200), 
	task_id INTEGER, 
	difficulty INTEGER, 
	is_correct BOOLEAN NOT NULL, 
	user_answer TEXT, 
