	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);CREATE TABLE topic_mastery (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	topic VARCHAR(100) NOT NULL, 
	grade INTEGER NOT NULL, 
	solved INTEGER, 
	attempts INTEGER, 
	avg_level FLOAT, 
	mastery FLOAT, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT _user_topic_grade_uc UNIQUE (user_id, topic, grade), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);INSERT INTO "topic_mastery" VALUES(1,1,'combinatorics',9,1,1,2.0,0.5,'2026-05-28 09:20:55.231813');INSERT INTO "topic_mastery" VALUES(2,1,'geometry',9,1,1,4.0,0.5,'2026-05-28 09:21:30.139668');CREATE TABLE tutor_calls (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    task_id INTEGER NOT NULL,
                    user_answer TEXT,
                    raw_response TEXT,
                    extracted_solution TEXT,
                    status TEXT,
                    validation_errors TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );INSERT INTO "tutor_calls" VALUES(1,5673,'3','{
  "my_solution": "Для пересекающихся хорд в окружности выполняется свойство: произведения отрезков, на которые точка пересечения делит каждую хорду, равны. То есть \\( AK \\cdot KB = CK \\cdot KD \\). Подставляем известные значения: \\( AK \\cdot 2 = 4 \\cdot 6 \\). Получаем \\( 2 \\cdot AK = 24 \\), откуда \\( AK = 12 \\).",
  "my_answer": "12",
  "user_correct": false,
  "explanation_for_student": "Ты почти угадал, но давай разберёмся внимательнее. В окружности для пересекающихся хорд есть важное свойство: произведения отрезков каждой хорды равны. У нас есть хорды AB и CD, они пересекаются в точке K. На хорде AB отрезки AK и KB, на хорде CD — CK и KD. По свойству: \\( AK \\cdot KB = CK \\cdot KD \\). Подставляем: \\( AK \\cdot 2 = 4 \\cdot 6 \\), то есть \\( 2 \\cdot AK = 24 \\). Делим обе части на 2 и получаем \\( AK = 12 \\). Твой ответ 3 не подходит, потому что при подстановке получилось бы \\( 3 \\cdot 2 = 6 \\), а \\( 4 \\cdot 6 = 24 \\), равенство не выполняется. Правильный ответ — 12.",
  "needs_review": false,
  "review_reason": "",
  "confidence": 0.95
}','Ты почти угадал, но давай разберёмся внимательнее. В окружности для пересекающихся хорд есть важное свойство: произведения отрезков каждой хорды равны. У нас есть хорды AB и CD, они пересекаются в точке K. На хорде AB отрезки AK и KB, на хорде CD — CK и KD. По свойству: \( AK \cdot KB = CK \cdot KD \). Подставляем: \( AK \cdot 2 = 4 \cdot 6 \), то есть \( 2 \cdot AK = 24 \). Делим обе части на 2 и получаем \( AK = 12 \). Твой ответ 3 не подходит, потому что при подстановке получилось бы \( 3 \cdot 2 = 6 \), а \( 4 \cdot 6 = 24 \), равенство не выполняется. Правильный ответ — 12.','ok','','2026-05-11 21:55:37');INSERT INTO "tutor_calls" VALUES(2,5702,'12','{
  "my_solution": "По свойству касательной и секущей: квадрат длины касательной равен произведению длины секущей на её внешнюю часть. То есть \( AB^2 = AC \\cdot AD \). Подставляем известные значения: \( 8^2 = 4 \\cdot AD \), \( 64 = 4 \\cdot AD \), откуда \( AD = 64 / 4 = 16 \).",
  "my_answer": "16",
  "user_correct": false,
  "explanation_for_student": "Ты почти угадал, но давай разберёмся точнее. Здесь работает свойство касательной и секущей: квадрат длины касательной равен произведению всей секущей на её внешнюю часть. У нас \( AB = 8 \), \( AC = 4 \) — это внешняя часть секущей. Тогда \( 8^2 = 4 \\cdot AD \), то есть \( 64 = 4 \\cdot AD \), значит \( AD = 16 \). Твой ответ 12 получился бы, если бы ты, например, сложил или вычел числа, но здесь нужно именно применить формулу. Попробуй запомнить это свойство — оно часто встречается в задачах с окружностью.",
  "needs_review": false,
  "review_reason": "",
  "confidence": 0.95
}','Разбор этой задачи временно недоступен.

**Правильный ответ: 16**

Попробуй решить её позже или обратись к учителю.','fallback','json_parse_error','2026-05-11 21:56:34');INSERT INTO "tutor_calls" VALUES(3,5635,'\frac32','{
  "my_solution": "Для решения задачи используем свойство секущих, проведённых из одной точки: произведение всей секущей на её внешнюю часть одинаково для обеих секущих. Для секущей AEF: внешняя часть AE = 2, вся секущая AF = AE + EF = 2 + 6 = 8. Произведение: AE * AF = 2 * 8 = 16. Для секущей ABC: внешняя часть AB — искомая, вся секущая AC = 12. Произведение: AB * AC = AB * 12. Приравниваем: AB * 12 = 16, откуда AB = 16 / 12 = 4/3.",
  "my_answer": "4/3",
  "user_correct": false,
  "explanation_for_student": "Ты почти правильно применил свойство секущих, но, возможно, ошибся в вычислениях. Давай разберёмся: из точки A проведены две секущие — AEF и ABC. Для первой секущей внешняя часть AE = 2, а вся секущая AF = AE + EF = 2 + 6 = 8. Произведение внешней части на всю секущую равно 2 * 8 = 16. Для второй секущей внешняя часть — это AB (её мы ищем), а вся секущая AC = 12. По свойству секущих: AB * 12 = 16. Отсюда AB = 16 / 12 = 4/3. Твой ответ 3/2 (или 1,5) не совпадает — проверь, не перепутал ли ты части секущих или не ошибся в арифметике. Правильный ответ: 4/3.",
  "needs_review": false,
  "review_reason": "",
  "confidence": 0.95
}','Ты почти правильно применил свойство секущих, но, возможно, ошибся в вычислениях. Давай разберёмся: из точки A проведены две секущие — AEF и ABC. Для первой секущей внешняя часть AE = 2, а вся секущая AF = AE + EF = 2 + 6 = 8. Произведение внешней части на всю секущую равно 2 * 8 = 16. Для второй секущей внешняя часть — это AB (её мы ищем), а вся секущая AC = 12. По свойству секущих: AB * 12 = 16. Отсюда AB = 16 / 12 = 4/3. Твой ответ 3/2 (или 1,5) не совпадает — проверь, не перепутал ли ты части секущих или не ошибся в арифметике. Правильный ответ: 4/3.','ok','','2026-05-11 22:07:41');INSERT INTO "tutor_calls" VALUES(4,3626,'\frac14','{
  "my_solution": "1. Введем координаты: пусть A(0,0), B(3,0) (чтобы удобно было делить AB в отношении 1:2). Тогда K делит AB в отношении AK:KB=1:2, значит K(1,0). 2. Пусть C(x_C, y_C). M — середина AC, поэтому M((x_C)/2, (y_C)/2). 3. Найдем точку пересечения O прямых BM и CK. Параметрически: BM: B + t*(M-B) = (3,0) + t*((x_C/2 - 3), (y_C/2)). CK: C + s*(K-C) = (x_C, y_C) + s*((1-x_C), (0-y_C)). 4. Приравниваем координаты: (3 + t*(x_C/2 - 3), t*y_C/2) = (x_C + s*(1-x_C), y_C - s*y_C). Из второго уравнения: t*y_C/2 = y_C - s*y_C => если y_C ≠ 0, то t/2 = 1 - s => s = 1 - t/2. 5. Из первого уравнения: 3 + t*(x_C/2 - 3) = x_C + (1 - t/2)*(1 - x_C). Раскрываем: 3 + t*x_C/2 - 3t = x_C + (1 - x_C) - (t/2)*(1 - x_C) = 1 - (t/2)*(1 - x_C). Переносим: 3 + t*x_C/2 - 3t = 1 - t/2 + t*x_C/2. Сокращаем t*x_C/2: 3 - 3t = 1 - t/2 => 2 = 3t - t/2 = (5/2)t => t = 4/5. 6. Точка O делит отрезок BM в отношении BO:OM = t:(1-t) = (4/5):(1/5) = 4:1.",
  "my_answer": "4:1",
  "user_correct": false,
  "explanation_for_student": "Ты записал ответ как \( \frac14 \), но это неверно. Отношение \(BO:OM\) равно \(4:1\), то есть \(BO\) в 4 раза больше \(OM\). В решении мы использовали координатный метод: взяли удобные координаты для точек, выразили параметрические уравнения прямых BM и CK, нашли параметр t, который показывает, как точка O делит отрезок BM. Получилось \(t = \frac45\), значит \(BO = \frac45 BM\), \(OM = \frac15 BM\), и отношение \(BO:OM = 4:1\). Проверь свои вычисления — возможно, ты перепутал, какую часть брать.",
  "needs_review": false,
  "review_reason": "",
  "confidence": 0.95
}','Ты записал ответ как \( rac14 \), но это неверно. Отношение \(BO:OM\) равно \(4:1\), то есть \(BO\) в 4 раза больше \(OM\). В решении мы использовали координатный метод: взяли удобные координаты для точек, выразили параметрические уравнения прямых BM и CK, нашли параметр t, который показывает, как точка O делит отрезок BM. Получилось \(t = rac45\), значит \(BO = rac45 BM\), \(OM = rac15 BM\), и отношение \(BO:OM = 4:1\). Проверь свои вычисления — возможно, ты перепутал, какую часть брать.','ok','','2026-05-12 18:41:44');INSERT INTO "tutor_calls" VALUES(5,3583,'30','{
  "my_solution": "Площадь треугольника можно найти по формуле: \( S = \\frac{1}{2} \\cdot AB \\cdot AC \\cdot \\sin A \). Подставляем значения: \( AB = 12 \) см, \( AC = 10 \) см, \( \\angle A = 30^\\circ \), \( \\sin 30^\\circ = \\frac{1}{2} \). Тогда \( S = \\frac{1}{2} \\cdot 12 \\cdot 10 \\cdot \\frac{1}{2} = \\frac{1}{2} \\cdot 120 \\cdot \\frac{1}{2} = 60 \\cdot \\frac{1}{2} = 30 \) см².",
  "my_answer": "30 см²",
  "user_correct": true,
  "explanation_for_student": "Ты верно нашёл площадь треугольника. В решении использована формула площади через две стороны и синус угла между ними: \( S = \\frac{1}{2} \\cdot AB \\cdot AC \\cdot \\sin A \). Подставив \( AB = 12 \) см, \( AC = 10 \) см и \( \\sin 30^\\circ = \\frac{1}{2} \), получаем \( S = \\frac{1}{2} \\cdot 12 \\cdot 10 \\cdot \\frac{1}{2} = 30 \) см². Отлично, ответ правильный!",
  "needs_review": false,
  "review_reason": "",
  "confidence": 1.0
}','Разбор этой задачи временно недоступен.

**Правильный ответ: 30 см²**

Попробуй решить её позже или обратись к учителю.','fallback','json_parse_error','2026-05-12 18:52:34');INSERT INTO "tutor_calls" VALUES(6,3626,'4','{
  "my_solution": "1. Пусть \(AB = 3\) (для удобства). Тогда \(AK = 1\), \(KB = 2\).\n2. Проведем через точку \(K\) прямую, параллельную \(BM\), до пересечения с \(AC\) в точке \(N\). По теореме Фалеса: \(AN:NC = AK:KB = 1:2\).\n3. Рассмотрим треугольник \(ABM\). В нем \(K\) лежит на \(AB\), \(KN \parallel BM\), значит \(AN:NM = AK:KB = 1:2\). Пусть \(NM = 2x\), тогда \(AN = x\).\n4. Так как \(BM\) — медиана, то \(AM = MC\). Выразим \(MC\) через \(x\): \(AM = AN + NM = x + 2x = 3x\), значит \(MC = 3x\).\n5. Теперь рассмотрим треугольник \(KMC\). Точка \(O\) — пересечение \(CK\) и \(BM\). Проведем через \(M\) прямую, параллельную \(CK\), до пересечения с \(AB\) в точке \(P\). По теореме Фалеса: \(KP:PB = KM:MC\). Но \(KM\) — часть \(BM\), и нам нужно найти \(BO:OM\).\n6. Используем метод масс или теорему Менелая для треугольника \(ABM\) и прямой \(CK\). Точки: \(C\) на \(AM\), \(K\) на \(AB\), \(O\) на \(BM\). По теореме Менелая: \(\frac{AK}{KB} \cdot \frac{BO}{OM} \cdot \frac{MC}{CA} = 1\).\n7. Подставим: \(\frac{1}{2} \cdot \frac{BO}{OM} \cdot \frac{MC}{CA} = 1\). \(MC = \frac{1}{2} AC\), так как \(M\) — середина \(AC\). Значит \(MC:CA = 1:2\).\n8. Получаем: \(\frac{1}{2} \cdot \frac{BO}{OM} \cdot \frac{1}{2} = 1\), то есть \(\frac{BO}{OM} \cdot \frac{1}{4} = 1\), откуда \(\frac{BO}{OM} = 4\).\n9. Итак, \(BO:OM = 4:1\).",
  "my_answer": "4:1",
  "user_correct": true,
  "explanation_for_student": "Ты верно нашел отношение \(BO:OM = 4:1\). В решении мы использовали теорему Менелая для треугольника \(ABM\) и секущей \(CK\). Обозначив \(AK:KB = 1:2\) и учитывая, что \(M\) — середина \(AC\), получили пропорцию, из которой \(BO:OM = 4:1\). Молодец!",
  "needs_review": false,
  "review_reason": "",
  "confidence": 0.95
}','Ты верно нашел отношение \(BO:OM = 4:1\). В решении мы использовали теорему Менелая для треугольника \(ABM\) и секущей \(CK\). Обозначив \(AK:KB = 1:2\) и учитывая, что \(M\) — середина \(AC\), получили пропорцию, из которой \(BO:OM = 4:1\). Молодец!','ok','','2026-05-12 18:57:06');INSERT INTO "tutor_calls" VALUES(7,3800,'2','{
  "my_solution": "1. Окружность касается стороны BC в точке M и продолжений сторон AB и AC за точки B и C соответственно. Это вневписанная окружность треугольника ABC, касающаяся стороны BC. \n2. Для вневписанной окружности, касающейся стороны BC, точка касания M делит сторону BC на отрезки: BM = (AB + BC - AC)/2, а MC = (AC + BC - AB)/2. \n3. Подставляем значения: AB = 5, BC = 7, AC = 8. \n4. BM = (5 + 7 - 8)/2 = (12 - 8)/2 = 4/2 = 2. \n5. Таким образом, длина отрезка BM равна 2.",
  "my_answer": "2",
  "user_correct": true,
  "explanation_for_student": "Ты правильно нашел ответ! Давай разберем решение подробнее. В задаче описана вневписанная окружность треугольника, которая касается стороны BC и продолжений двух других сторон. Для такой окружности есть формула: отрезок от вершины B до точки касания M на стороне BC равен (AB + BC - AC)/2. Подставляем числа: (5 + 7 - 8)/2 = 4/2 = 2. Твой ответ верный!",
  "needs_review": true,
  "review_reason": "Ответ из БД (5) неверен. Правильный ответ — 2, полученный по формуле для вневписанной окружности. Возможно, в БД ошибочно указан ответ для другой конфигурации.",
  "confidence": 0.95
}','Ты правильно нашел ответ! Давай разберем решение подробнее. В задаче описана вневписанная окружность треугольника, которая касается стороны BC и продолжений двух других сторон. Для такой окружности есть формула: отрезок от вершины B до точки касания M на стороне BC равен (AB + BC - AC)/2. Подставляем числа: (5 + 7 - 8)/2 = 4/2 = 2. Твой ответ верный!','ok','','2026-05-12 20:28:58');INSERT INTO "tutor_calls" VALUES(8,3788,'ч⋅т⋅д','{
  "my_solution": "1. В остроугольном треугольнике \(ABC\) точки \(A_1, B_1, C_1\) — основания высот, поэтому они лежат на окружности девяти точек треугольника \(ABC\).\n\n2. Окружность, проходящая через \(A_1, B_1, C_1\), — это окружность девяти точек. Она пересекает стороны \(AB, BC, CA\) вторично в точках \(C_2, A_2, B_2\) соответственно. Эти точки являются основаниями высот треугольника \(ABC\)? Нет, основания высот уже \(A_1, B_1, C_1\). На самом деле, окружность девяти точек пересекает стороны в серединах отрезков от вершин до ортоцентра. Но здесь указано \"вторично\", то есть после точек \(A_1, B_1, C_1\)? Нет, \(A_1\) лежит на \(BC\), \(B_1\) на \(CA\), \(C_1\) на \(AB\). Окружность девяти точек пересекает каждую сторону в двух точках: одна — основание высоты, другая — середина отрезка от вершины до ортоцентра. Таким образом, \(A_2\) — это середина отрезка \(AH\), где \(H\) — ортоцентр, и аналогично для \(B_2\) и \(C_2\).\n\n3. Прямые \(AA_2, BB_2, CC_2\) проходят через вершины и середины отрезков от вершин до ортоцентра. Эти прямые являются симедианами треугольника \(ABC\). Симедианы пересекаются в точке Лемуана.\n\n4. Таким образом, отрезки \(AA_2, BB_2, CC_2\) пересекаются в одной точке — точке Лемуана треугольника \(ABC\).",
  "my_answer": "Отрезки \(AA_2, BB_2, CC_2\) пересекаются в точке Лемуана треугольника \(ABC\).",
  "user_correct": false,
  "explanation_for_student": "Ты написал ''ч⋅т⋅д'', что означает ''что и требовалось доказать'', но это не является доказательством. Нужно показать, что отрезки пересекаются в одной точке. В решении мы выяснили, что точки \(A_2, B_2, C_2\) — это середины отрезков от вершин до ортоцентра. Прямые, соединяющие вершины с этими точками, являются симедианами, а все симедианы пересекаются в точке Лемуана. Таким образом, утверждение доказано.",
  "needs_review": false,
  "review_reason": "",
  "confidence": 0.95
}','Ты написал ''ч⋅т⋅д'', что означает ''что и требовалось доказать'', но это не является доказательством. Нужно показать, что отрезки пересекаются в одной точке. В решении мы выяснили, что точки \(A_2, B_2, C_2\) — это середины отрезков от вершин до ортоцентра. Прямые, соединяющие вершины с этими точками, являются симедианами, а все симедианы пересекаются в точке Лемуана. Таким образом, утверждение доказано.','ok','','2026-05-12 20:33:50');INSERT INTO "tutor_calls" VALUES(9,3626,'нафото\text{ видно}','{
  "my_solution": "1. Введем векторные обозначения. Пусть \( \vec{BA} = \vec{a} \), \( \vec{BC} = \vec{c} \). Тогда \( \vec{BM} = \frac{\vec{a} + \vec{c}}{2} \), так как \(M\) — середина \(AC\).\n2. Точка \(K\) делит \(AB\) в отношении \(AK:KB = 1:2\), значит \( \vec{BK} = \frac{2}{3} \vec{BA} = \frac{2}{3} \vec{a} \).\n3. Точка \(O\) лежит на \(BM\), поэтому \( \vec{BO} = t \cdot \vec{BM} = t \cdot \frac{\vec{a} + \vec{c}}{2} \), где \(t = \frac{BO}{BM}\).\n4. Точка \(O\) также лежит на \(CK\). Выразим \( \vec{CO} \) через \( \vec{CK} \): \( \vec{CO} = s \cdot \vec{CK} \), где \(s = \frac{CO}{CK}\). Имеем \( \vec{CK} = \vec{CB} + \vec{BK} = -\vec{c} + \frac{2}{3} \vec{a} \).\n5. С другой стороны, \( \vec{CO} = \vec{CB} + \vec{BO} = -\vec{c} + t \cdot \frac{\vec{a} + \vec{c}}{2} = -\vec{c} + \frac{t}{2} \vec{a} + \frac{t}{2} \vec{c} = \frac{t}{2} \vec{a} + \left( \frac{t}{2} - 1 \right) \vec{c} \).\n6. Приравниваем: \( s \left( -\vec{c} + \frac{2}{3} \vec{a} \right) = \frac{t}{2} \vec{a} + \left( \frac{t}{2} - 1 \right) \vec{c} \).\n7. Поскольку \(\vec{a}\) и \(\vec{c}\) линейно независимы, получаем систему:\n   \[
   \begin{cases}
   \frac{2}{3} s = \frac{t}{2} \\
   -s = \frac{t}{2} - 1
   \end{cases}
   \]\n8. Из первого уравнения: \( s = \frac{3t}{4} \). Подставляем во второе: \( -\frac{3t}{4} = \frac{t}{2} - 1 \). Умножаем на 4: \( -3t = 2t - 4 \), откуда \( 5t = 4 \), \( t = \frac{4}{5} \).\n9. Значит, \( BO = \frac{4}{5} BM \), а \( OM = BM - BO = \frac{1}{5} BM \). Следовательно, \( BO:OM = 4:1 \).",
  "my_answer": "4:1",
  "user_correct": false,
  "explanation_for_student": "Твой ответ не распознан (возможно, фото не загрузилось). Давай разберем задачу вместе. Мы используем векторный метод: обозначаем векторы сторон, выражаем точки пересечения через параметры и решаем систему. В итоге получаем, что \(BO:OM = 4:1\). Попробуй решить самостоятельно, следуя шагам, и запиши ответ в виде отношения.",
  "needs_review": false,
  "review_reason": "",
  "confidence": 0.95
}','Разбор этой задачи временно недоступен.

**Правильный ответ: 4:1**

Попробуй решить её позже или обратись к учителю.','fallback','json_parse_error','2026-05-12 20:40:55');INSERT INTO "tutor_calls" VALUES(10,3525,'НЕТУ','{
  "my_solution": "Уравнение \(\frac{x^2 - 4x + 3}{x - a} = 0\) равносильно системе: \[ \begin{cases} x^2 - 4x + 3 = 0, \\ x - a \neq 0. \end{cases} \] Решаем числитель: \(x^2 - 4x + 3 = 0\). Дискриминант \(D = 16 - 12 = 4\), корни: \(x = \frac{4 \pm 2}{2}\), то есть \(x_1 = 1\), \(x_2 = 3\). Уравнение имеет ровно одно решение, если один из этих корней не удовлетворяет условию \(x \neq a\), то есть совпадает с \(a\). Таким образом, \(a\) должно быть равно 1 или 3. При \(a = 1\) корень \(x = 1\) исключается, остаётся только \(x = 3\). При \(a = 3\) корень \(x = 3\) исключается, остаётся только \(x = 1\). Если \(a\) равно любому другому числу, оба корня допустимы, и решений будет два. Следовательно, \(a = 1\) или \(a = 3\).",
  "my_answer": "a = 1, a = 3",
  "user_correct": false,
  "explanation_for_student": "Уравнение \(\frac{x^2 - 4x + 3}{x - a} = 0\) — это дробь, равная нулю. Дробь равна нулю, когда числитель равен нулю, а знаменатель не равен нулю. Решаем числитель: \(x^2 - 4x + 3 = 0\). Находим корни: \(x = 1\) и \(x = 3\). Чтобы уравнение имело ровно одно решение, нужно, чтобы один из этих корней «выпал» из-за знаменателя. Это происходит, если \(a\) совпадает с одним из корней: при \(a = 1\) корень \(x = 1\) не подходит (деление на ноль), остаётся только \(x = 3\); при \(a = 3\) корень \(x = 3\) не подходит, остаётся только \(x = 1\). Таким образом, правильные значения параметра: \(a = 1\) и \(a = 3\). Твой ответ «НЕТУ» неверен, так как такие значения существуют.",
  "needs_review": false,
  "review_reason": "",
  "confidence": 1.0
}','Разбор этой задачи временно недоступен.

**Правильный ответ: a = 1, a = 3**

Попробуй решить её позже или обратись к учителю.','fallback','json_parse_error','2026-05-13 15:07:33');INSERT INTO "tutor_calls" VALUES(11,3481,'\left(4,3\right)\text{ И (3,4)}','{
  "my_solution": "1. Из второго уравнения выразим y = 12/x (при x ≠ 0). 2. Подставим в первое: x² + (12/x)² = 25 → x² + 144/x² = 25. 3. Умножим на x²: x⁴ + 144 = 25x² → x⁴ - 25x² + 144 = 0. 4. Сделаем замену t = x², t ≥ 0: t² - 25t + 144 = 0. 5. Решаем квадратное уравнение: D = 625 - 576 = 49, t₁ = (25 + 7)/2 = 16, t₂ = (25 - 7)/2 = 9. 6. Обратная замена: x² = 16 → x = ±4; x² = 9 → x = ±3. 7. Находим y: при x = 4, y = 12/4 = 3; при x = -4, y = 12/(-4) = -3; при x = 3, y = 12/3 = 4; при x = -3, y = 12/(-3) = -4. 8. Получаем четыре решения: (4; 3), (3; 4), (-4; -3), (-3; -4).",
  "my_answer": "(4; 3), (3; 4), (-4; -3), (-3; -4)",
  "user_correct": false,
  "explanation_for_student": "Ты верно нашел две пары решений: (4; 3) и (3; 4). Но в системе есть еще два решения с отрицательными знаками: (-4; -3) и (-3; -4). Проверь: если подставить x = -4, y = -3 в уравнения, получим (-4)² + (-3)² = 16 + 9 = 25 и (-4)·(-3) = 12 — всё верно. При решении через подстановку y = 12/x не забывай, что x может быть и отрицательным, так как квадрат дает положительное значение. Попробуй перерешать, учитывая оба знака корня.",
  "needs_review": false,
  "review_reason": "",
  "confidence": 0.95
}','Ты верно нашел две пары решений: (4; 3) и (3; 4). Но в системе есть еще два решения с отрицательными знаками: (-4; -3) и (-3; -4). Проверь: если подставить x = -4, y = -3 в уравнения, получим (-4)² + (-3)² = 16 + 9 = 25 и (-4)·(-3) = 12 — всё верно. При решении через подстановку y = 12/x не забывай, что x может быть и отрицательным, так как квадрат дает положительное значение. Попробуй перерешать, учитывая оба знака корня.','ok','','2026-05-13 15:12:23');INSERT INTO "tutor_calls" VALUES(12,3837,'96','{
  "my_solution": "1. Всего перестановок цифр 1,2,3,4,5: 5! = 120.\n2. Чётные цифры: 2 и 4. Нечётные: 1,3,5.\n3. Сначала расставим нечётные цифры: 3! = 6 способов. Они образуют 4 промежутка (до, между, после): _ Н _ Н _ Н _.\n4. Выбираем 2 промежутка из 4 для чётных цифр: C(4,2) = 6 способов.\n5. В выбранные промежутки чётные цифры можно расставить 2! = 2 способами.\n6. Итого: 6 * 6 * 2 = 72.",
  "my_answer": "72",
  "user_correct": false,
  "explanation_for_student": "Давай разберёмся вместе. Нам нужно, чтобы чётные цифры (2 и 4) не стояли рядом. Сначала расставим нечётные цифры (1,3,5) — это 3! = 6 способов. Они создают 4 места, куда можно вставить чётные цифры: до первой нечётной, между нечётными и после последней. Выбираем 2 места из 4 — это C(4,2) = 6 способов. В выбранные места чётные цифры можно поставить 2! = 2 способами. Перемножаем: 6 × 6 × 2 = 72. Твой ответ 96 получился, возможно, из-за того, что ты не учёл, что чётные цифры не могут стоять рядом, и посчитал все перестановки без ограничения. Попробуй ещё раз по этому алгоритму.",
  "needs_review": false,
  "review_reason": "",
  "confidence": 0.95
}','Давай разберёмся вместе. Нам нужно, чтобы чётные цифры (2 и 4) не стояли рядом. Сначала расставим нечётные цифры (1,3,5) — это 3! = 6 способов. Они создают 4 места, куда можно вставить чётные цифры: до первой нечётной, между нечётными и после последней. Выбираем 2 места из 4 — это C(4,2) = 6 способов. В выбранные места чётные цифры можно поставить 2! = 2 способами. Перемножаем: 6 × 6 × 2 = 72. Твой ответ 96 получился, возможно, из-за того, что ты не учёл, что чётные цифры не могут стоять рядом, и посчитал все перестановки без ограничения. Попробуй ещё раз по этому алгоритму.','ok','','2026-05-13 15:32:51');INSERT INTO "tutor_calls" VALUES(13,61,'30','{
  "my_solution": "Обозначим первоначальное количество яблок за \(x\). После того как Петя отдал половину своих яблок и ещё одно яблоко Васе, у него осталось: \(x - \left(\frac{x}{2} + 1\right) = \frac{x}{2} - 1\). Затем он отдал половину оставшихся яблок и ещё одно яблоко Коле: \(\frac{1}{2}\left(\frac{x}{2} - 1\right) + 1 = \frac{x}{4} - \frac{1}{2} + 1 = \frac{x}{4} + \frac{1}{2}\). После этого осталось: \(\left(\frac{x}{2} - 1\right) - \left(\frac{x}{4} + \frac{1}{2}\right) = \frac{x}{4} - \frac{3}{2}\). По условию это равно 5: \(\frac{x}{4} - \frac{3}{2} = 5\). Умножаем на 4: \(x - 6 = 20\), откуда \(x = 26\).",
  "my_answer": "26",
  "user_correct": false,
  "explanation_for_student": "Давай разберём задачу по шагам. Пусть у Пети было \(x\) яблок. Сначала он отдал Васе половину всех яблок и ещё одно: \(\frac{x}{2} + 1\). Осталось: \(x - \left(\frac{x}{2} + 1\right) = \frac{x}{2} - 1\). Затем он отдал Коле половину оставшихся и ещё одно: \(\frac{1}{2}\left(\frac{x}{2} - 1\right) + 1 = \frac{x}{4} + \frac{1}{2}\). После этого осталось: \(\left(\frac{x}{2} - 1\right) - \left(\frac{x}{4} + \frac{1}{2}\right) = \frac{x}{4} - \frac{3}{2}\). По условию это 5, значит \(\frac{x}{4} - \frac{3}{2} = 5\). Умножаем на 4: \(x - 6 = 20\), откуда \(x = 26\). Ты получил 30 — возможно, ошибка в расчёте остатка после второго шага. Попробуй проверить ещё раз, подставив 26: после первого шага остаётся 12, после второго — 5, всё сходится.",
  "needs_review": false,
  "review_reason": "",
  "confidence": 0.95
}','Давай разберём задачу по шагам. Пусть у Пети было \(x\) яблок. Сначала он отдал Васе половину всех яблок и ещё одно: \(rac{x}{2} + 1\). Осталось: \(x - \left(rac{x}{2} + 1ight) = rac{x}{2} - 1\). Затем он отдал Коле половину оставшихся и ещё одно: \(rac{1}{2}\left(rac{x}{2} - 1ight) + 1 = rac{x}{4} + rac{1}{2}\). После этого осталось: \(\left(rac{x}{2} - 1ight) - \left(rac{x}{4} + rac{1}{2}ight) = rac{x}{4} - rac{3}{2}\). По условию это 5, значит \(rac{x}{4} - rac{3}{2} = 5\). Умножаем на 4: \(x - 6 = 20\), откуда \(x = 26\). Ты получил 30 — возможно, ошибка в расчёте остатка после второго шага. Попробуй проверить ещё раз, подставив 26: после первого шага остаётся 12, после второго — 5, всё сходится.','ok','','2026-05-13 15:43:03');INSERT INTO "tutor_calls" VALUES(14,1,'1','{
  "my_solution": "1. Сначала выполняем умножение и деление: \(17 \\times 4 = 68\), \(36 \\div 3 = 12\).\n2. Затем подставляем: \(25 + 68 - 12\).\n3. Выполняем сложение и вычитание по порядку: \(25 + 68 = 93\), \(93 - 12 = 81\).",
  "my_answer": "81",
  "user_correct": false,
  "explanation_for_student": "Ты получил 1, но правильный ответ — 81. Ошибка в том, что ты, возможно, выполнил действия не в правильном порядке. В математике сначала делают умножение и деление, а потом сложение и вычитание. Давай разберём: сначала \(17 \\times 4 = 68\) и \(36 \\div 3 = 12\). Теперь выражение: \(25 + 68 - 12\). Считаем по порядку: \(25 + 68 = 93\), затем \(93 - 12 = 81\). Попробуй ещё раз, и всё получится!",
  "needs_review": false,
  "review_reason": "",
  "confidence": 1.0
}','Разбор этой задачи временно недоступен.

**Правильный ответ: 81**

Попробуй решить её позже или обратись к учителю.','fallback','json_parse_error','2026-05-13 15:43:34');INSERT INTO "tutor_calls" VALUES(15,3480,'нет\text{ таких a}','{
  "my_solution": "1. Уравнение \(\frac{x^2 - 2x + a}{x - 1} = 0\) определено при \(x \neq 1\).\n2. Дробь равна нулю, когда числитель равен нулю, а знаменатель не равен нулю: \(x^2 - 2x + a = 0\) и \(x \neq 1\).\n3. Квадратное уравнение \(x^2 - 2x + a = 0\) имеет дискриминант \(D = 4 - 4a\).\n4. Условие ровно одного решения: либо квадратное уравнение имеет один корень (кратности 2), и этот корень не равен 1, либо квадратное уравнение имеет два различных корня, но один из них равен 1 (тогда он исключается, и остается только второй корень).\n5. Случай 1: \(D = 0 \Rightarrow 4 - 4a = 0 \Rightarrow a = 1\). Тогда корень \(x = 1\) (так как \(x = \frac{2}{2} = 1\)). Но \(x = 1\) не входит в ОДЗ, поэтому решений нет. Не подходит.\n6. Случай 2: \(D > 0\) и один из корней равен 1. Подставим \(x = 1\) в числитель: \(1 - 2 + a = 0 \Rightarrow a = 1\). При \(a = 1\) получаем корень \(x = 1\) (кратности 2), что уже рассмотрено. Других значений нет.\n7. Таким образом, ни при каких \(a\) уравнение не имеет ровно одного решения: либо два решения (если \(D > 0\) и корни не равны 1), либо одно решение, но оно исключается ОДЗ, либо нет решений.",
  "my_answer": "Нет таких значений \(a\)",
  "user_correct": true,
  "explanation_for_student": "Ты верно заметил, что таких значений \(a\) нет. Давай разберем подробнее. Уравнение \(\frac{x^2 - 2x + a}{x - 1} = 0\) имеет смысл только при \(x \neq 1\). Дробь равна нулю, когда числитель равен нулю. Рассмотрим квадратное уравнение \(x^2 - 2x + a = 0\). Если у него один корень (дискриминант равен нулю), то это \(x = 1\) при \(a = 1\), но этот корень не подходит по ОДЗ. Если два различных корня, то один из них может быть равен 1, но тогда \(a = 1\) и второй корень тоже равен 1 (так как сумма корней 2), то есть опять получаем только \(x = 1\). Таким образом, ни при каком \(a\) не получается ровно одно допустимое решение.",
  "needs_review": false,
  "review_reason": "",
  "confidence": 0.95
}','Ты верно заметил, что таких значений \(a\) нет. Давай разберем подробнее. Уравнение \(rac{x^2 - 2x + a}{x - 1} = 0\) имеет смысл только при \(x 
eq 1\). Дробь равна нулю, когда числитель равен нулю. Рассмотрим квадратное уравнение \(x^2 - 2x + a = 0\). Если у него один корень (дискриминант равен нулю), то это \(x = 1\) при \(a = 1\), но этот корень не подходит по ОДЗ. Если два различных корня, то один из них может быть равен 1, но тогда \(a = 1\) и второй корень тоже равен 1 (так как сумма корней 2), то есть опять получаем только \(x = 1\). Таким образом, ни при каком \(a\) не получается ровно одно допустимое решение.','ok','','2026-05-13 21:17:44');INSERT INTO "tutor_calls" VALUES(16,3527,'-3-2-\text{  }1\text{ }2','{
  "my_solution": "1. Рассмотрим неравенство \(|x-2| + |x+3| \le 6\). Найдем точки, где модули меняют знак: \(x=2\) и \(x=-3\). Они разбивают числовую прямую на три промежутка.\n\n2. **Первый промежуток:** \(x < -3\). Тогда \(|x-2| = 2-x\), \(|x+3| = -x-3\). Неравенство: \(2-x - x - 3 \le 6\) → \(-2x -1 \le 6\) → \(-2x \le 7\) → \(x \ge -3.5\). С учетом \(x < -3\) получаем \(-3.5 \le x < -3\). Целые числа: \(-3\).\n\n3. **Второй промежуток:** \(-3 \le x \le 2\). Тогда \(|x-2| = 2-x\), \(|x+3| = x+3\). Неравенство: \(2-x + x+3 \le 6\) → \(5 \le 6\) — верно для всех \(x\) из этого промежутка. Целые числа: \(-3, -2, -1, 0, 1, 2\).\n\n4. **Третий промежуток:** \(x > 2\). Тогда \(|x-2| = x-2\), \(|x+3| = x+3\). Неравенство: \(x-2 + x+3 \le 6\) → \(2x+1 \le 6\) → \(2x \le 5\) → \(x \le 2.5\). С учетом \(x > 2\) получаем \(2 < x \le 2.5\). Целых чисел нет.\n\n5. Объединяя все целые решения: \(-3, -2, -1, 0, 1, 2\).",
  "my_answer": "-3, -2, -1, 0, 1, 2",
  "user_correct": false,
  "explanation_for_student": "Ты записал ответ как ''-3-2- 1 2'', но это не совсем верный формат. Правильный ответ — это множество целых чисел: -3, -2, -1, 0, 1, 2. Давай разберем решение. Неравенство с модулями решается разбиением числовой прямой на промежутки. Точки смены знака модулей: x = -3 и x = 2. На промежутке от -3 до 2 неравенство выполняется для всех x, так как сумма модулей равна 5, что меньше 6. На левом промежутке (x < -3) получаем x ≥ -3.5, то есть целое -3. На правом (x > 2) — x ≤ 2.5, целых нет. Итого все целые от -3 до 2 включительно. Твой ответ неполный — пропущены 0 и, возможно, другие числа. Попробуй записать их через запятую.",
  "needs_review": false,
  "review_reason": "",
  "confidence": 0.95
}','Ты записал ответ как ''-3-2- 1 2'', но это не совсем верный формат. Правильный ответ — это множество целых чисел: -3, -2, -1, 0, 1, 2. Давай разберем решение. Неравенство с модулями решается разбиением числовой прямой на промежутки. Точки смены знака модулей: x = -3 и x = 2. На промежутке от -3 до 2 неравенство выполняется для всех x, так как сумма модулей равна 5, что меньше 6. На левом промежутке (x < -3) получаем x ≥ -3.5, то есть целое -3. На правом (x > 2) — x ≤ 2.5, целых нет. Итого все целые от -3 до 2 включительно. Твой ответ неполный — пропущены 0 и, возможно, другие числа. Попробуй записать их через запятую.','ok','','2026-05-13 21:23:30');INSERT INTO "tutor_calls" VALUES(17,3178,'фото','{
  "my_solution": "Разложим \(x^4+4\) на множители. Заметим, что \(x^4+4 = x^4+4x^2+4 - 4x^2 = (x^4+4x^2+4) - (2x)^2 = (x^2+2)^2 - (2x)^2\). Теперь применим формулу разности квадратов: \((x^2+2)^2 - (2x)^2 = (x^2+2-2x)(x^2+2+2x) = (x^2-2x+2)(x^2+2x+2)\).",
  "my_answer": "(x²-2x+2)(x²+2x+2)",
  "user_correct": false,
  "explanation_for_student": "Ты прислал фото, но я не могу его прочитать. Давай разберем задачу вместе. Чтобы разложить \(x^4+4\), нужно добавить и вычесть \(4x^2\): \(x^4+4 = x^4+4x^2+4 - 4x^2\). Первые три слагаемых образуют полный квадрат: \((x^2+2)^2\), а \(-4x^2\) запишем как \(-(2x)^2\). Получаем разность квадратов: \((x^2+2)^2 - (2x)^2 = (x^2+2-2x)(x^2+2+2x)\). Итоговый ответ: \((x^2-2x+2)(x^2+2x+2)\). Попробуй переписать решение и сверить с ответом.",
  "needs_review": false,
  "review_reason": "",
  "confidence": 1.0
}','Ты прислал фото, но я не могу его прочитать. Давай разберем задачу вместе. Чтобы разложить \(x^4+4\), нужно добавить и вычесть \(4x^2\): \(x^4+4 = x^4+4x^2+4 - 4x^2\). Первые три слагаемых образуют полный квадрат: \((x^2+2)^2\), а \(-4x^2\) запишем как \(-(2x)^2\). Получаем разность квадратов: \((x^2+2)^2 - (2x)^2 = (x^2+2-2x)(x^2+2+2x)\). Итоговый ответ: \((x^2-2x+2)(x^2+2x+2)\). Попробуй переписать решение и сверить с ответом.','ok','','2026-05-17 15:51:12');INSERT INTO "tutor_calls" VALUES(18,301,'3\text{ }-2','{
  "my_solution": "1. Введем замену: \( t = x^2 - x \). Тогда уравнение примет вид \( t^2 - 8t + 12 = 0 \).\n2. Решаем квадратное уравнение: \( t^2 - 8t + 12 = 0 \). Дискриминант: \( D = (-8)^2 - 4 \cdot 1 \cdot 12 = 64 - 48 = 16 \). Корни: \( t_1 = \frac{8 + 4}{2} = 6 \), \( t_2 = \frac{8 - 4}{2} = 2 \).\n3. Возвращаемся к замене:\n   - \( x^2 - x = 6 \) → \( x^2 - x - 6 = 0 \). Дискриминант: \( D = 1 + 24 = 25 \). Корни: \( x = \frac{1 \pm 5}{2} \), то есть \( x_1 = 3 \), \( x_2 = -2 \).\n   - \( x^2 - x = 2 \) → \( x^2 - x - 2 = 0 \). Дискриминант: \( D = 1 + 8 = 9 \). Корни: \( x = \frac{1 \pm 3}{2} \), то есть \( x_3 = 2 \), \( x_4 = -1 \).\n4. Итого, уравнение имеет четыре корня: \( -2, -1, 2, 3 \).",
  "my_answer": "-2; -1; 2; 3",
  "user_correct": false,
  "explanation_for_student": "Ты указал только два корня: 3 и -2. Однако уравнение имеет четыре решения. Давай разберемся подробнее. Сначала сделаем замену \( t = x^2 - x \), тогда получим квадратное уравнение \( t^2 - 8t + 12 = 0 \). Его корни: \( t = 6 \) и \( t = 2 \). Теперь решаем два уравнения: \( x^2 - x = 6 \) дает корни 3 и -2, а \( x^2 - x = 2 \) дает корни 2 и -1. Таким образом, полный набор корней: -2, -1, 2, 3. Попробуй подставить каждый из них в исходное уравнение, чтобы убедиться.",
  "needs_review": false,
  "review_reason": "",
  "confidence": 1.0
}','Ты указал только два корня: 3 и -2. Однако уравнение имеет четыре решения. Давай разберемся подробнее. Сначала сделаем замену \( t = x^2 - x \), тогда получим квадратное уравнение \( t^2 - 8t + 12 = 0 \). Его корни: \( t = 6 \) и \( t = 2 \). Теперь решаем два уравнения: \( x^2 - x = 6 \) дает корни 3 и -2, а \( x^2 - x = 2 \) дает корни 2 и -1. Таким образом, полный набор корней: -2, -1, 2, 3. Попробуй подставить каждый из них в исходное уравнение, чтобы убедиться.','ok','','2026-05-23 17:04:08');INSERT INTO "tutor_calls" VALUES(19,735,'не\text{ знаю}','{
  "my_solution": "1. Подставим \(n = 10\) в выражение \(n^3 - n\).\n2. Вычислим \(10^3 = 1000\).\n3. Вычтем \(n = 10\): \(1000 - 10 = 990\).",
  "my_answer": "990",
  "user_correct": false,
  "explanation_for_student": "Давай разберем эту задачу вместе. Нам нужно найти значение выражения \(n^3 - n\) при \(n = 10\). Сначала подставляем число вместо буквы: \(10^3 - 10\). \(10^3\) — это \(10 \cdot 10 \cdot 10 = 1000\). Теперь вычитаем 10: \(1000 - 10 = 990\). Ответ: 990. Если что-то осталось непонятным, спроси — я помогу!",
  "needs_review": false,
  "review_reason": "",
  "confidence": 1.0
}','Давай разберем эту задачу вместе. Нам нужно найти значение выражения \(n^3 - n\) при \(n = 10\). Сначала подставляем число вместо буквы: \(10^3 - 10\). \(10^3\) — это \(10 \cdot 10 \cdot 10 = 1000\). Теперь вычитаем 10: \(1000 - 10 = 990\). Ответ: 990. Если что-то осталось непонятным, спроси — я помогу!','ok','','2026-05-24 18:24:22');INSERT INTO "tutor_calls" VALUES(20,449,'не\text{ знаю}','{
  "my_solution": "1. Дано: треугольник ABC. Точка M на AB: AM=4, MB=6, значит AB=AM+MB=4+6=10. Точка N на AC: AN=5, NC=7.5, значит AC=AN+NC=5+7.5=12.5.\n2. Проверим пропорциональность отрезков: AM/AB = 4/10 = 2/5, AN/AC = 5/12.5 = 50/125 = 2/5. Так как AM/AB = AN/AC и угол A общий, то треугольники AMN и ABC подобны по второму признаку (две стороны пропорциональны и угол между ними равен).\n3. Коэффициент подобия k = AM/AB = 2/5. Следовательно, отношение соответствующих сторон MN и BC равно k = 2/5.\n4. Ответ: MN:BC = 2:5.",
  "my_answer": "2:5",
  "user_correct": false,
  "explanation_for_student": "Давай разберём задачу вместе. У нас есть треугольник ABC, на стороне AB отмечена точка M так, что AM=4, MB=6, значит вся сторона AB=10. На стороне AC точка N: AN=5, NC=7.5, значит AC=12.5. Обрати внимание: отношение AM к AB равно 4/10 = 2/5, и отношение AN к AC равно 5/12.5 = 2/5. Поскольку эти отношения равны и угол A общий, треугольники AMN и ABC подобны. В подобных треугольниках все соответствующие стороны относятся одинаково, поэтому MN:BC = AM:AB = 2:5. Твой ответ ''не знаю'' — это нормально, теперь ты знаешь решение!",
  "needs_review": false,
  "review_reason": "",
  "confidence": 0.95
}','Давай разберём задачу вместе. У нас есть треугольник ABC, на стороне AB отмечена точка M так, что AM=4, MB=6, значит вся сторона AB=10. На стороне AC точка N: AN=5, NC=7.5, значит AC=12.5. Обрати внимание: отношение AM к AB равно 4/10 = 2/5, и отношение AN к AC равно 5/12.5 = 2/5. Поскольку эти отношения равны и угол A общий, треугольники AMN и ABC подобны. В подобных треугольниках все соответствующие стороны относятся одинаково, поэтому MN:BC = AM:AB = 2:5. Твой ответ ''не знаю'' — это нормально, теперь ты знаешь решение!','ok','','2026-05-24 18:29:24');INSERT INTO "tutor_calls" VALUES(21,308,'3,\text{ }2','{
  "my_solution": "Решим систему: \\(x + y = 5\\) и \\(x^2 + y^2 = 13\\). Выразим \\(y = 5 - x\\) из первого уравнения и подставим во второе: \\(x^2 + (5 - x)^2 = 13\\). Раскроем скобки: \\(x^2 + 25 - 10x + x^2 = 13\\), получим \\(2x^2 - 10x + 25 = 13\\). Перенесем 13: \\(2x^2 - 10x + 12 = 0\\), разделим на 2: \\(x^2 - 5x + 6 = 0\\). Решаем квадратное уравнение: дискриминант \\(D = 25 - 24 = 1\\), корни \\(x_1 = \\frac{5 + 1}{2} = 3\\), \\(x_2 = \\frac{5 - 1}{2} = 2\\). Тогда \\(y_1 = 5 - 3 = 2\\), \\(y_2 = 5 - 2 = 3\\). Получаем две пары решений: \\((3; 2)\\) и \\((2; 3)\\).",
  "my_answer": "(3; 2) и (2; 3)",
  "user_correct": true,
  "explanation_for_student": "Ты верно нашел одну из пар — (3; 2). Но система имеет два решения: (3; 2) и (2; 3). В своем ответе ты указал только одну пару, а нужно было записать обе. В остальном ход решения правильный — молодец!",
  "needs_review": false,
  "review_reason": "",
  "confidence": 0.95
}','Ты верно нашел одну из пар — (3; 2). Но система имеет два решения: (3; 2) и (2; 3). В своем ответе ты указал только одну пару, а нужно было записать обе. В остальном ход решения правильный — молодец!','ok','','2026-05-25 17:05:26');CREATE TABLE user_presence (
	user_id INTEGER NOT NULL, 
	last_seen DATETIME NOT NULL, 
	typing_to_id INTEGER, 
	typing_at DATETIME, 
	PRIMARY KEY (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(typing_to_id) REFERENCES users (id) ON DELETE SET NULL
);CREATE TABLE user_progress (
	user_id INTEGER NOT NULL, 
	topic VARCHAR(200) NOT NULL, 
	class_level INTEGER NOT NULL, 
	rating FLOAT, 
	tasks_solved INTEGER, 
	tasks_attempted INTEGER, 
	current_difficulty INTEGER, 
	last_activity DATETIME, 
	PRIMARY KEY (user_id, topic, class_level), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);CREATE TABLE user_streaks (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	current_streak INTEGER, 
	longest_streak INTEGER, 
	last_active_date DATE, 
	freeze_available INTEGER, 
	freeze_used_at DATE, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);INSERT INTO "user_streaks" VALUES(1,1,0,0,NULL,1,NULL,'2026-05-27 22:36:26.549135','2026-05-27 22:36:26.549139');CREATE TABLE user_topic_progress (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
